Your expense tracker is below. Add an amount, pick a category and a date, and it totals the month and shows where the money goes. It also warns you when you pass your budget. It keeps entries on this page, and they may not be saved after you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:14px;background:#fafafa;color:#222}
h2{margin:0 0 10px;font-size:18px}
.card{background:#fff;border:1px solid #e3e3e3;border-radius:10px;padding:12px;margin-bottom:12px}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:110px}
button{background:#0b6bcb;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.big{font-size:26px;font-weight:600}
.bar{height:8px;background:#e8eef7;border-radius:4px;margin:3px 0 8px}
.bar>div{height:8px;background:#0b6bcb;border-radius:4px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
.sub{color:#777;font-size:12px}
.warn{color:#b00;font-weight:600}
.ok{color:#127a3a}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
 <div class="row">
  <input id="d" placeholder="What was it for?">
  <input id="a" type="number" min="0" placeholder="Amount (₹)">
 </div>
 <div class="row" style="margin-top:8px">
  <select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option></select>
  <input id="t" type="date">
  <button id="add">Add</button>
 </div>
</div>
<div class="card">
 <div class="row" style="align-items:center;justify-content:space-between">
  <div>
   <select id="m"></select>
   <div class="big" id="tot">₹0</div>
   <div class="sub" id="cnt"></div>
  </div>
  <div>
   <div class="sub">Monthly budget (₹)</div>
   <input id="b" type="number" min="0" placeholder="e.g. 50000">
   <div id="bs" class="sub"></div>
  </div>
 </div>
</div>
<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>
<script>
var mem={e:[],b:0},store=null;
try{store=window.localStorage;store.setItem('t','1');store.removeItem('t')}catch(x){store=null}
function load(){try{if(store){var s=store.getItem('exp');if(s)mem=JSON.parse(s)}}catch(x){}}
function save(){try{if(store)store.setItem('exp',JSON.stringify(mem))}catch(x){}}
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
function $(i){return document.getElementById(i)}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
var today=new Date().toISOString().slice(0,10);
$('t').value=today;
load();
$('b').value=mem.b||'';
function months(){
  var set={};set[today.slice(0,7)]=1;
  mem.e.forEach(function(x){set[x.date.slice(0,7)]=1});
  var cur=$('m').value;
  var keys=Object.keys(set).sort().reverse();
  $('m').innerHTML=keys.map(function(k){
    var d=new Date(k+'-01T00:00:00Z');
    return '<option value="'+k+'">'+d.toLocaleString('en-IN',{month:'long',year:'numeric',timeZone:'UTC'})+'</option>'}).join('');
  $('m').value=keys.indexOf(cur)>=0?cur:keys[0];
}
function render(){
  var mk=$('m').value;
  var rows=mem.e.map(function(x,i){x.i=i;return x}).filter(function(x){return x.date.slice(0,7)===mk}).sort(function(a,b){return a.date<b.date?1:-1});
  var tot=rows.reduce(function(s,x){return s+x.amt},0);
  $('tot').textContent=inr(tot);
  $('cnt').textContent=rows.length+' entries';
  var bud=Number($('b').value)||0;
  $('bs').innerHTML=bud?(tot>bud?'<span class="warn">Over by '+inr(tot-bud)+'</span>':'<span class="ok">'+inr(bud-tot)+' left</span>'):'';
  var by={};rows.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a]});
  $('cats').innerHTML=keys.length?keys.map(function(k){
    var p=tot?by[k]/tot*100:0;
    return '<div class="item" style="border:0;padding:0"><span>'+k+'</span><span>'+inr(by[k])+' <span class="sub">('+Math.round(p)+'%)</span></span></div><div class="bar"><div style="width:'+p+'%"></div></div>'}).join(''):'<div class="sub">Nothing yet.</div>';
  $('list').innerHTML=rows.length?rows.map(function(x){
    return '<div class="item"><div>'+esc(x.desc||x.cat)+'<div class="sub">'+x.cat+' · '+x.date+'</div></div><div>'+inr(x.amt)+' <button class="x" data-i="'+x.i+'">✕</button></div></div>'}).join(''):'<div class="sub">No entries for this month.</div>';
}
$('add').onclick=function(){
  var a=Number($('a').value);
  if(!(a>0)){$('a').focus();return}
  mem.e.push({desc:$('d').value.trim(),amt:a,cat:$('c').value,date:$('t').value||today});
  $('d').value='';$('a').value='';save();months();
  $('m').value=(mem.e[mem.e.length-1].date).slice(0,7);render();
};
$('list').onclick=function(ev){
  var i=ev.target.getAttribute&&ev.target.getAttribute('data-i');
  if(i!==null&&i!==undefined){mem.e.splice(Number(i),1);save();months();render()}
};
$('m').onchange=render;
$('b').oninput=function(){mem.b=Number($('b').value)||0;save();render()};
months();render();
</script></body></html>
```
